  "👥 อาจารย์ — NC ศ.น.สพ.ดร.นิวัตร จันทร์ศิริพรชัย (ผู้ประสานงาน), CI ศ.น.สพ.ดร.ชัยเดช อินทร์ชัยศรี, VH ผศ.น.สพ.ดร.วชิรา หุ่นประสิทธิ์, SJ รศ.สพ.ญ.ดร.สหฤทัย เจียมศรีพงษ์, TC อ.สพ.ญ.ดร.ฐนิชา ชาญชัยเดชาชัย, NB สพ.ญ.นพวรรณ บัวมีธูป": "👥 Lecturers — NC Prof. Dr. Niwat Chansiripornchai (coordinator), CI Prof. Dr. Chaidech Inchaisri, VH Asst. Prof. Dr. Wachira Hunprasit, SJ Assoc. Prof. Dr. Saharuetai Jeamsripong, TC Aj. Dr. Thanicha Chanchai, NB Dr. Noppawan Buameethup",
