  "🗓 ปลายภาค: HACCP และมาตรฐานส่งออก (14 ต.ค.), สัตว์น้ำและผลิตภัณฑ์ (28 ต.ค.), ตรวจสอบคุณภาพเนื้อสัตว์ (11 พ.ย. 69)": "🗓 Final scope — HACCP and export standards (14 Oct), aquatic animals and their products (28 Oct), meat quality inspection (11 Nov 2026)",
  "🗓 ไม่มีสอบกลางภาคตามตารางสอบทางการ 2569 — เนื้อหาบรรยาย 3 ส.ค. ถึง 14 ก.ย. 69 รวมสอบปลายภาค 4 ธ.ค. 69 เวลา 08.30-11.30": "🗓 The official 2026 exam schedule lists no midterm. Lectures from 3 Aug to 14 Sep 2026 are included in the final on 4 Dec 2026, 08:30-11:30",
  "🗓 ไม่มีสอบกลางภาคและปลายภาคในตารางสอบฝ่ายวิชาการ ภาคต้น 2569 (Update 20 ก.ค. 69) — ประเมินจากงานระหว่างเรียน": "🗓 The Academic Affairs exam schedule for first semester 2026 (updated 20 Jul 2026) lists no midterm or final. Assessment is based on assignments during the semester",
  "🗓 Final 23 พ.ย. – 4 ธ.ค. 69 — ครึ่ง \"สุขศาสตร์เนื้อสัตว์\" เริ่ม 30 ก.ย. (Cleaning) ถึง 18 พ.ย.": "🗓 Final 23 Nov – 4 Dec 2026 — covers the \"Meat hygiene\" half, from 30 Sep (Cleaning) to 18 Nov",
