  "3 หน่วยกิต (2.0-0.0-4.0) ตัดเกรดอิงเกณฑ์ A ≥ 80, B+ ≥ 75, B ≥ 70, C+ ≥ 65, C ≥ 60, D+ ≥ 55, D ≥ 50": "3 credits (2.0-0.0-4.0), criterion-based grading: A ≥ 80, B+ ≥ 75, B ≥ 70, C+ ≥ 65, C ≥ 60, D+ ≥ 55, D ≥ 50",
