  "52 ข้อจาก \"Final Exotic ไม่ใช่คำตอบ.pdf\", cover ND (15), AE (10), aMPV (5), APEC (10), Mycoplasma (4), Coryza/cholera/NDS (8). เนื้อหาเป็นโรคพื้นฐานของ poultry — ปกติสอนใน midterm Y4 แต่ Palm สงสัยว่าอาจเป็น Y5 Avian Med": "52 questions from \"Final Exotic ไม่ใช่คำตอบ.pdf\" cover ND (15), AE (10), aMPV (5), APEC (10), Mycoplasma (4), and Coryza/cholera/NDS (8). These are common poultry diseases usually taught for the Year 4 midterm. Palm thinks they may be from Year 5 Avian Med.",
  "5 ข้อ (2 match-type 12 ท่า A-L + 3 MCQ correction), อาจารย์บอกออกข้อสอบวาดรูปคลอดยาก ต้องเตรียมดินสอ+ยางลบ, หมาหอนนี้ฝึก map ชื่อ/ท่า ก่อน + รู้วิธี mutation ก่อนวาด": "5 questions (2 matching questions on 12 fetal positions A-L + 3 MCQs on correction). The lecturer said the exam includes a dystocia drawing question and to bring a pencil and eraser. Use this cram set to match names to positions and review mutation before drawing.",
  "5 ข้อ ปรนัย — อ.น้ำบอกแนวข้อสอบ \"ชนิดของอาหารหยาบและประเมินคุณภาพอาหารหยาบหมัก\", หัวข้อหลัก: กลิ่น (เปรี้ยว lactic), pH<4, สี (เขียวปนน้ำตาล), ความชื้น 60-70%, ระยะเวลาหมัก 21d ขั้นต่ำ": "5 multiple-choice questions. Aj. Nam identified \"types of roughage and silage quality assessment\" as the exam topic. Main points include odor (sour, lactic), pH<4, color (greenish brown), moisture 60-70%, and at least 21 days of fermentation.",
  "5 ข้อ — สูตร DMI, R:C ratio (50:50 high-yield), Particle size >19mm peNDF, NEL คือ, NDF vs ADF, จาก Feed mgt page ของ (Final) PDF p2": "5 questions from the Feed mgt page of the (Final) PDF, p2 — DMI formula, R:C ratio (50:50 high-yield), Particle size >19mm peNDF, what NEL means, and NDF vs ADF",
  "5 พ.ค. 2569, 13:00-16:00, VET6 B01-B03": "5 May 2026, 13:00-16:00, VET6 B01-B03",
  "5 มี.ค., คาบ 15": "5 Mar, session 15",
