  "/6, กดวงกลมเพื่อระบุข้อที่ถูก)": "/6, select the circle next to the correct option)",
  "6 ข้อ — Palm เพื่อนถามมา, อ.บอกอ่านคร่าวๆ ให้รู้หลักการ, 3 types penile deviation (spiral/ventral/S-shape) + apical ligament + reinforcement surgery + caudal epididymectomy → teaser bull concept": "6 questions. A friend asked Palm about this, and the lecturer advised a quick review of the principles. Covers 3 types of penile deviation (spiral/ventral/S-shape) + apical ligament + reinforcement surgery + caudal epididymectomy → teaser bull concept.",
  "6 ประเภท: MCQ (4-5 ช้อยส์), True/False, Fill-in, Matching, ตอบสั้น และเขียนตอบ": "6 types: MCQ (4–5 options), True/False, Fill-in, Matching, short answer, and written response",
