  "ข้อมูลการเรียนในบัญชีเก็บจนคุณลบหรือสั่งลบบัญชี ห้องแข่งมีอายุ 24 ชั่วโมง และล้างห้องหมดอายุเมื่อมีการสร้างห้องใหม่ ผลการแข่งขันยังอยู่ในประวัติจนลบบัญชี การลบบัญชีลบข้อมูลที่ผูกกับบัญชีบนระบบ แต่ไฟล์ที่ดาวน์โหลดและข้อมูลในเบราว์เซอร์อุปกรณ์อื่นยังต้องลบจากอุปกรณ์นั้นเอง ระบบสำรองของผู้ให้บริการอาจยังเก็บข้อมูลตามรอบของผู้ให้บริการ": "Your study data stays in your account until you delete it or request account deletion. Race rooms expire after 24 hours. The app clears expired rooms when someone creates a new room. Race results stay in your history until you delete your account. Deleting your account removes the data linked to it from the service. Delete downloaded files and browser data on other devices directly from those devices. Service providers may retain backups according to their own retention schedules.",
