  "ข้อสอบส่วนตัวมีรหัสซ้ำกับข้อมูลบัญชี ข้อมูลในเครื่องยังอยู่ครบ กรุณาสำรองแล้วนำเข้าข้อนั้นใหม่เพื่อรับรหัสใหม่": "A custom question shares an ID with your account data. Your local data is intact. Back it up, then import the question again to give it a new ID.",
