  "ข้อสอบหมวดละ 150 ข้อ แบบ 5 ตัวเลือก เป็นข้อสอบความจำราว 50-60 ข้อ และข้อสอบประยุกต์ราว 90-100 ข้อ ผ่านเมื่อได้ 55% ของแต่ละหมวด หรือ 83 ข้อ": "Each section has 150 questions with 5 options, including about 50-60 recall questions and 90-100 application questions. The passing score is 55%, or 83 correct answers, in each section",
