  "เขียนในกรอบด้วยนิ้ว ปากกา หรือ Apple Pencil (เมื่อใช้ปากกา ฝ่ามือที่วางบนจอจะไม่ถูกนับ) แล้วกด แปลงเป็นข้อความ ข้อความจะไปต่อท้ายในช่องคำตอบให้ตรวจและแก้ก่อนส่ง เขียนตัวใหญ่ตามเส้นบรรทัด ทีละหนึ่งหรือสองบรรทัด อ่านได้แม่นกว่า": "Write in the box with a finger, stylus, or Apple Pencil (the screen ignores your palm when you use a stylus). Select Convert to text to add it to the end of your answer. Review and edit before you submit. Write large and follow the lines, one or two at a time, for better recognition.",
