  "ตารางเรียน 2569 คาบ 14 ส.ค. 69 ระบุ สพ.ญ.ดร. วลีมาศ ใจรักษ์, น.สพ. ชนกันต์ นาสำราญ และ อ.สพ.ญ.ดร. กมลพรรณ เจริญกุล ผู้ประสานรายวิชา เนื้อหาคาบนี้บรรยายโดยวิทยากรรับเชิญที่เป็นนิสิตปริญญาเอก ร่วมกับผู้ดำเนินคาบ ในคลิปไม่ได้เอ่ยชื่อเต็ม": "The 2026 schedule lists Dr. Waleemas Jairak, Dr. Chanakan Nasamran, and course coordinator Aj. Dr. Kamonpan Charoenkul for 14 Aug 2026. A guest doctoral student taught the session with the session lead. The clip gives no full name",
  "ตารางเรียน 2569 คาบ 14 ส.ค. 69 ระบุ สพ.ญ.ดร. วลีมาศ ใจรักษ์, น.สพ. ชนกันต์ นาสำราญ และ อ.สพ.ญ.ดร. กมลพรรณ เจริญกุล ผู้ประสานรายวิชา ส่วนโคโรนาไวรัสย้ายไป 28 ส.ค. เนื้อหาคาบนี้บรรยายโดยวิทยากรรับเชิญที่เป็นนิสิตปริญญาเอก ร่วมกับผู้ดำเนินคาบ ในคลิปไม่ได้เอ่ยชื่อเต็ม": "The 2026 schedule lists Dr. Waleemas Jairak, Dr. Chanakan Nasamran, and course coordinator Aj. Dr. Kamonpan Charoenkul for 14 Aug 2026. The coronavirus topic moved to 28 Aug. A guest doctoral student taught this session with the session lead. The clip gives no full name",
  "ตารางเรียน 2569 คาบ 4 ก.ย. 69 ระบุ นพ.พีริยะ วตะกูลสิน กรมควบคุมโรค และท่านแนะนำตัวในคาบ": "The 2026 schedule lists Dr. Piriya Watakulsin of the Department of Disease Control for 4 Sep 2026. He introduces himself in the session",
  "ตารางเรียน 2569 คาบ 7 ส.ค. 69 ระบุวิทยากร สพ.ญ.ดร. นภวัลย์ บรรพพงศ์, สพ.ญ.ดร. สุภณัฐ บุญญาภิสิทธิโสภา และ สพ.ญ.ดร. สุพัศมา ไชยวงศ์ ร่วมกับผู้ประสานรายวิชา อ.สพ.ญ.ดร. กมลพรรณ เจริญกุล ในคลิปวิทยากรแนะนำตัวด้วยชื่อเล่น จึงยังจับคู่ชื่อเต็มไม่ได้": "The 2026 schedule lists Dr. Napawan Buppapong, Dr. Supanat Boonyapisitsopa, and Dr. Supatsama Chaiwong with course coordinator Aj. Dr. Kamonpan Charoenkul for 7 Aug 2026. The speakers use nicknames in the clip, so their full names are still unconfirmed",
