  "เนื้อหา": "Content",
  "— เนื้อหาจากสไลด์เลกเชอร์ปี 2569 และสรุปรุ่นพี่ โดยระบุแหล่งที่มาในแต่ละส่วน": "— From 2026 lecture slides and summaries by seniors, with sources in each section",
  "เนื้อหาตรวจกับแหล่งที่มาที่ระบุไว้ใต้เฉลย แต่ยังอาจมีข้อผิดพลาดได้ ใช้ประกอบการอ่านเอกสารของผู้สอนเสมอ ถ้าพบจุดที่ผิด แจ้งได้ที่หน้าแจ้งปัญหา เนื้อหาใช้เพื่อการศึกษาเท่านั้น ไม่ใช่คำแนะนำในการวินิจฉัยหรือรักษาสัตว์ป่วยจริง": "We check content against the sources listed below each answer, but errors can still occur. Always use it alongside your lecturer's materials. If you spot an error, use the Report a problem page. This content is for education only. Do not use it to diagnose or treat an animal.",
  "เนื้อหาทั้งวิชาอยู่ในช่วง{a} ({b} ข้อ) ตามตารางเรียนปีนี้": {"one":"This year's teaching schedule puts the whole subject in the {a} period ({b} question).","other":"This year's teaching schedule puts the whole subject in the {a} period ({b} questions)."},
  "เนื้อหาทั้งหมดของวิชาอยู่ในอีกช่วงสอบหนึ่ง ตามตารางเรียนปีนี้": "This year's teaching schedule puts the whole subject in the other exam period.",
