  "เนื้อหาทั้งหมดมาจากสไลด์ {a} วิชา{b} ({c}) โดย{d} ซึ่งอยู่ในคลังเอกสารของแอป ตัวเลขในโต๊ะทดลองคำนวณสดจากค่าที่ตั้ง ไม่ได้พิมพ์ค้างไว้": "All content comes from the {a} slides for {b} ({c}) by {d}, available in the library. The experiment values are recalculated live as you change the settings.",
