  "โมเดลกะโหลกสุนัขจาก CT ที่ผู้สร้างเตรียมสำหรับพิมพ์ 3D ไม่ระบุอายุ เพศ หรือสายพันธุ์ และการอยู่ในคลัง NIH ไม่ได้หมายถึงการรับรองทางคลินิก": "A canine skull model from CT that its creator prepared for 3D printing. Age, sex and breed are not given, and being in the NIH library does not mean clinical validation.",
