  "โมเดล German Shepherd รุ่นทำงานจาก SimTK: โครงกระดูก 24 ส่วนและแนวกล้ามเนื้อจำลอง 158 แนว บางส่วนรวมกระดูกหลายชิ้น เส้นแสดงแนวในแบบจำลองแรง ไม่ใช่รูปร่างหรือความหนาจริงของกล้ามเนื้อ ชุดนี้ไม่มีผิวหนังและอวัยวะภายใน รูปร่างหลังแปลงและคำไทยยังรอทบทวน": "A working German Shepherd model from SimTK: 24 skeletal segments and 158 modeled muscle paths. Some segments join several bones. The lines are paths in a force model, not the real shape or thickness of the muscles. The set has no skin or internal organs. The converted shapes and the Thai terms are still awaiting review.",
