  "รายงานข้อผิดพลาดเก็บเพียงจำนวนครั้ง แยกตาม รุ่นเว็บ, ชื่อหน้า (ไม่ใช่ที่อยู่เว็บ), ชนิดของปัญหา, ประเภทของ error, ข้อความ error เฉพาะแบบที่เบราว์เซอร์สร้างเอง (เลขยาว ลิงก์ และข้อความในเครื่องหมายคำพูดถูกแทนด้วยเครื่องหมาย ข้อความแบบอื่นเก็บเป็นรหัสสั้นแทน ไม่เก็บตัวข้อความ) และชื่อไฟล์โค้ดของเว็บพร้อมเลขบรรทัด ไม่เก็บชื่อ อีเมล บัญชี คำตอบ หรือโน้ตของใคร รายการนับล้างเมื่อเกิน 14 วัน": "Error reporting stores only occurrence counts, grouped by web version, page name (not URL), issue type, error category, browser-generated error message, and source file name and line number. In browser messages, symbols replace long numbers, links, and quoted text. For other messages, the report stores a short code in place of the text. Reports contain no names, email addresses, account details, answers, or notes. Counts are cleared after 14 days.",
  "รายงานจากเบราว์เซอร์ของผู้ใช้ เก็บย้อนหลัง 14 วัน แยกตามวัน เวอร์ชัน และหน้า": "Reports from users' browsers over the last 14 days, grouped by day, version, and page.",
