  "เว็บไซต์ให้บริการผ่าน Vercel และใช้ Supabase สำหรับบัญชีและฐานข้อมูล การตรวจสรุปหรือขอคำอธิบายส่งเฉพาะข้อความที่เลือกไปยังผู้ให้บริการประมวลผลที่ระบบตั้งค่า การอ่านออกเสียงใช้ iApp หรือผู้ให้บริการเสียง ส่วนวิดีโอภายนอกเช่น YouTube อยู่ภายใต้นโยบายของเว็บไซต์นั้น": "Vercel hosts the site, and Supabase provides accounts and the database. When you check a summary or request an explanation, the app sends only the selected text to its configured processing provider. Read-aloud uses iApp or another voice provider. External videos, such as YouTube videos, follow the hosting site's policy.",
  "เว็บนี้เป็น unofficial และไม่มีความเกี่ยวข้องกับคณะสัตวแพทยศาสตร์ จุฬาฯ อย่างเป็นทางการ เนื้อหาเป็น": "This is an unofficial site with no formal affiliation with the Faculty of Veterinary Science at Chulalongkorn University. The site contains ",
