  "สอนหลังกลางภาค (คาบ 9 ต.ค. 2569) จึงยังนับเป็นเนื้อหาปลายภาค แต่อาจารย์บอกว่าเรื่อง management ในคาบนี้ให้รู้ไว้ใช้ตอนฝึกงาน (นาที 4:23) และคาดว่าปลายภาคส่วนของท่านน่าจะเหลือเฉพาะ reproductive disease (นาที 112:05-112:18)": "The 9 Oct 2026 session falls after the midterm and remains in the final scope. The lecturer said the management material is for placements (4:23) and expects their part of the final to cover only reproductive disease (112:05-112:18)",
