  "สิ่งที่พังในเบราว์เซอร์ของนิสิต บัญชีใหม่ที่สร้างโปรไฟล์ไม่สำเร็จ และงานอัตโนมัติทุกตัว จำนวนเป็นค่าต่ำสุด: แต่ละเบราว์เซอร์ส่งได้ 20 รายงานต่อหน้า และแต่ละ IP 50 รายงานต่อวัน (นิสิตที่ใช้เน็ตมหาวิทยาลัยใช้ IP ร่วมกัน) ส่วนที่อ่านไม่ได้จะบอกว่าอ่านไม่ได้": "Errors in student browsers, new accounts where profile creation failed, and all automated jobs. Counts are minimums. Each browser can send 20 reports per page, and each IP can send 50 reports per day (students on the university network share an IP). Unreadable sections are marked as such.",
  "สิทธิ์รีวิวเปิดให้ผู้ที่เคยส่งคำถามผ่านการตรวจทานมาแล้วหลายข้อ — ทีมงานจะเปิดสิทธิ์ให้เองเมื่อถึงเกณฑ์ เริ่มจากส่งคำถามเข้ามาก่อนได้เลย": "The team grants review access once several of your submitted questions pass review and you meet the criteria. Start by submitting a question.",
