  "สุนัขทั้งตัวและอวัยวะ": "Visible dog whole-body anatomy",
  "สุนัข Beagle จากชุด Visible dog: ผิวโมเดล 32 ชิ้นใน 12 ระบบ เก็บชื่อและพิกัดร่วมจากต้นฉบับ PRC กล้ามเนื้อและโครงกระดูกเป็นชิ้นรวม บางอวัยวะแยกซ้าย–ขวาได้ ไม่ใช้วัดระยะจริง ศัพท์บางรายการ เช่น Sigmoid colon ยังรอทบทวนตามกายวิภาคสัตวแพทย์": "A Beagle from the Visible dog set: 32 model surfaces in 12 systems, with names and shared coordinates kept from the PRC source. Muscles and skeleton are each one combined piece; some organs split into left and right. Not for real measurements. Some terms, such as Sigmoid colon, are still awaiting review against veterinary anatomy.",
