  "อ.": "Tue",
  "อ.ธนศักดิ์ (TB) จากปก slide 2026 GI_VDTT.pdf, \"Ruminant Gastrointestinal Disorder\", Internal medicine approach: GI atony / Hyper-Hypomotility / Acidosis (pH <5.5) / Alkalosis (>7.0 inactivate rumen) / Methylene blue test (3-6 min normal) / Sediment activity 4-8 min / Gram stain rumen fluid (gram+ predominate normal, gram- shift = acidosis)": "Aj. Thanasak (TB), as listed on the 2026 GI_VDTT.pdf slide cover, \"Ruminant Gastrointestinal Disorder\". Internal medicine approach: GI atony / Hyper-Hypomotility / Acidosis (pH <5.5) / Alkalosis (>7.0 inactivate rumen) / Methylene blue test (3-6 min normal) / Sediment activity 4-8 min / Gram stain rumen fluid (gram+ predominate normal, gram- shift = acidosis)",
  "อธิบายปัญหา/ข้อเสนอแนะ…": "Describe the problem or share feedback…",
  "อธิบายว่าทำไม Q นี้ไม่ผ่าน, contributor จะเห็นเหตุผลและ Q จะถูก reject ออกจาก queue": "Explain why this Q didn't pass. The contributor will see your reason, and rejecting the Q removes it from the queue.",
  "อธิบายว่า contributor ควรแก้อะไร, จะส่งกลับให้แก้ใหม่ (revise)": "Explain what the contributor should change. The submission will go back for revision (revise).",
  "อธิบายสั้นๆ": "Explain briefly",
  "อธิบายแหล่งที่มา (เช่น \"Aj. Nan slide สัปดาห์ 3\")": "Describe the source (e.g., \"Aj. Nan’s slides, week 3\").",
  "อนุญาตไมค์ในเบราว์เซอร์ก่อน": "Allow microphone access in your browser.",
  "อนุญาตแล้ว": "Allowed",
  "อนุญาต analytics": "Allow analytics",
  "อ.ปิยะณัฐ (PP) สอนทั้ง Metabolism+Nutrition และ Hoof Health ใน Clin App Rum 2026, Clinical Dashboard Framework 5 sections: DMI / Nutritional values / Nutrient requirements / R:C ratio + milk fat / Particle size, Transition period, Subclinical Ketosis, NEB, Feces Score 1-5, Locomotion Score 1-5, BCS": "Aj. Piyanat (PP) teaches both Metabolism+Nutrition and Hoof Health in Clin App Rum 2026. The 5 Clinical Dashboard Framework sections are DMI / Nutritional values / Nutrient requirements / R:C ratio + milk fat / Particle size. Other topics include Transition period, Subclinical Ketosis, NEB, Feces Score 1-5, Locomotion Score 1-5, and BCS.",
  "อยากใช้รหัสผ่าน?": "Want to use a password?",
