  "เอฟเฟกต์ฉลองใช้เมื่อทำชุดฝึกสำเร็จ ส่วนโหมดสอบจะเก็บเฉลยไว้จนส่งคำตอบ แถบเปอร์เซ็นต์ใช้กับงานที่วัดความคืบหน้าได้เท่านั้น": "Celebration effects play when you finish a practice set. In exam mode, answers stay hidden until you submit. The percentage bar appears only when progress can be measured.",
