  "แอปจะเตือนทุกวันเวลา {a} น. ถ้าวันนั้นทำโจทย์แล้วจะไม่เตือน": "The app will remind you daily at {a} if you haven't practiced that day.",
  "แอปจะอ่านอย่างเดียว ไม่แก้ไขและไม่ลบ ยกเลิกได้ที่ปุ่มในกล่องนี้หรือหน้าตั้งค่าของผู้ให้บริการ": "The app has read-only access. Disconnect here or in the provider's settings.",
  "แอปใช้ข้อมูลชุดเดียวกับเว็บตามที่เขียนไว้ในหน้านี้ และเก็บเพิ่มไว้ในโทรศัพท์เท่านั้น ได้แก่ วันที่ฝึกต่อเนื่อง จำนวนข้อที่ฝึกวันนี้ วันสอบถัดไป เวลาเตือน และธีมที่เลือก เพื่อแสดงในวิดเจ็ตหน้าจอหลักและการเตือนวันละครั้ง การเตือนคำนวณและแสดงในเครื่อง ไม่ส่งข้อมูลออก แอปขอสิทธิ์แจ้งเตือนเมื่อคุณเลือกเปิดเท่านั้น และดาวน์โหลดไฟล์รุ่นใหม่ของตัวเองจาก vetmock.com โดยตรวจทุกไฟล์ก่อนใช้": "The app uses the same data as the website, as described on this page. It stores your practice streak dates, today's practice question count, next exam date, reminder time, and chosen theme only on your phone for the home screen widget and daily reminder. Your phone schedules and shows reminders locally without sending any data. The app asks for notification permission only when you turn reminders on. It downloads its update files from vetmock.com and checks each file before using it.",
  "แอปที่เชื่อมไว้": "Connected apps",
